  LISTCAT ENTRIES(MY.DATASET) ALL
/*

//CATLIST  JOB (ACCT),'LIST CAT',CLASS=A,MSGCLASS=X
//IDCAMS   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
