  LISTCAT LEVEL(SYS1) ALL
/*

//DELVSAM  JOB (ACCT),'DEL VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DELETE MY.VSAM.CLUSTER CLUSTER PURGE
/*

//DEFKSDS  JOB (ACCT),'DEF KSDS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DEFINE CLUSTER (NAME(MY.VSAM.KSDS) -
    INDEXED -
    KEYS(8 0) -
    RECORDSIZE(100 100) -
    TRACKS(10 5)) -
  DATA (NAME(MY.VSAM.KSDS.DATA)) -
  INDEX (NAME(MY.VSAM.KSDS.INDEX))
/*

//SORTJOB  JOB (ACCT),'SORT FILE',CLASS=A,MSGCLASS=X
//SORT     EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT  DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5))
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
/*

//SORTDATA JOB (ACCT),'SORT DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=MY.INPUT.FILE,DISP=SHR
//SORTOUT  DD DSN=MY.OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5))
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
/*

//COMPRESS JOB (ACCT),'COMPRESS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBCOPY
