//SYSUT2   DD SYSOUT=*
//SYSIN    DD *
  PRINT MAXFLDS=1
  RECORD FIELD=(80)
/*

//CONCAT   JOB (ACCT),'CONCAT DS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSIN    DD DUMMY
//SYSUT1   DD DSN=FIRST.DATASET,DISP=SHR
//         DD DSN=SECOND.DATASET,DISP=SHR
//SYSUT2   DD DSN=COMBINED.DATASET,DISP=(NEW,CATLG,DELETE),
