//SYSPRINT DD SYSOUT=*

//RUNJOB   JOB (ACCT),'RUN PROG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=MYPROG
//STEPLIB  DD DSN=MY.LOAD.LIBRARY,DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSOUT   DD SYSOUT=*
//INPUT    DD DSN=MY.INPUT.FILE,DISP=SHR
//OUTPUT   DD DSN=MY.OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5))

//INLINE   JOB (ACCT),'INLINE COB',CLASS=A,MSGCLASS=X
//COMPILE  EXEC PGM=IGYCRCTL
//STEPLIB  DD DSN=IGY.V6R3M0.SIGYCOMP,DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSLIN   DD DSN=&&OBJ,DISP=(MOD,PASS),UNIT=SYSDA,SPACE=(TRK,(3,3))
//SYSUT1   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT2   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT3   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT4   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT5   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT6   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSUT7   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSIN    DD *
       IDENTIFICATION DIVISION.
       PROGRAM-ID. HELLO.
       PROCEDURE DIVISION.
           DISPLAY 'HELLO WORLD'.
           STOP RUN.
/*

//PROCJOB  JOB (ACCT),'USE PROC',CLASS=A,MSGCLASS=X
//STEP1    EXEC PROC=MYPROC,PARM='TEST'
//STEP1.INPUT DD DSN=MY.INPUT.DATA,DISP=SHR

//MYPROC   PROC
//STEP1    EXEC PGM=MYPROG
//STEPLIB  DD DSN=MY.LOAD.LIBRARY,DISP=SHR
//SYSPRINT DD SYSOUT=*
//INPUT    DD DSN=&INFILE,DISP=SHR
//OUTPUT   DD DSN=&OUTFILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5))
//         PEND

//BACKUP   JOB (ACCT),'BACKUP DS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSIN    DD DUMMY
//SYSUT1   DD DSN=PROD.IMPORTANT.DATA,DISP=SHR
//SYSUT2   DD DSN=BACKUP.IMPORTANT.DATA,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(100,50))

//COMPARE  JOB (ACCT),'COMPARE',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBCOMPR
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=FIRST.DATASET,DISP=SHR
//SYSUT2   DD DSN=SECOND.DATASET,DISP=SHR
//SYSIN    DD *
  COMPARE TYPORG=PS
/*

//RENAME   JOB (ACCT),'RENAME DS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  ALTER OLD.DATASET.NAME -
    NEWNAME(NEW.DATASET.NAME)
/*

//REPROJOB JOB (ACCT),'REPRO',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//INFILE   DD DSN=MY.VSAM.FILE,DISP=SHR
//OUTFILE  DD DSN=MY.SEQ.BACKUP,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(50,25))
//SYSIN    DD *
  REPRO INFILE(INFILE) OUTFILE(OUTFILE)
/*

//SYMJOB   JOB (ACCT),'SYMBOLIC',CLASS=A,MSGCLASS=X
// SET INDSN=MY.INPUT.DATA
// SET OUTDSN=MY.OUTPUT.DATA
//STEP1    EXEC PGM=MYPROG
//INPUT    DD DSN=&INDSN,DISP=SHR
//OUTPUT   DD DSN=&OUTDSN,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5))

//GENDATA  JOB (ACCT),'GEN DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DUMMY
//SORTOUT  DD DSN=TEST.DATA.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5)),
//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=8000)
//SYSIN    DD *
  OPTION COPY
  OUTFIL REPEAT=100,OUTREC=(1:C'TEST RECORD')
/*

//IFJOB    JOB (ACCT),'IF THEN',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=PROG1
//IF1      IF (STEP1.RC = 0) THEN
//STEP2    EXEC PGM=PROG2
//ELSE1    ELSE
//STEP3    EXEC PGM=ERRORPGM
//ENDIF1   ENDIF

//REXXJOB  JOB (ACCT),'RUN REXX',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IKJEFT01
//SYSTSPRT DD SYSOUT=*
//SYSTSIN  DD *
  %MYREXX
/*
//SYSEXEC  DD DSN=MY.REXX.LIBRARY,DISP=SHR

//TSOJOB   JOB (ACCT),'TSO CMD',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IKJEFT01
//SYSTSPRT DD SYSOUT=*
//SYSTSIN  DD *
  LISTDS 'SYS1.PARMLIB' MEMBERS
  LISTCAT LEVEL(SYS1)
/*

//WTOR     JOB (ACCT),'OPER MSG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSIN    DD DUMMY
//SYSUT1   DD DSN=MY.DATA,DISP=SHR
//SYSUT2   DD SYSOUT=*
//*
//* Note: Use WTOR macro in assembler for actual operator reply

//FTPJOB   JOB (ACCT),'FTP FILE',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=FTP,PARM='(EXIT'
//SYSPRINT DD SYSOUT=*
//OUTPUT   DD SYSOUT=*
//INPUT    DD *
  REMOTE.HOST.COM
  USER
  PASSWORD
  CD /home/user
  PUT 'MY.DATASET' file.txt
  QUIT
/*

//GDGBASE  JOB (ACCT),'DEF GDG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DEFINE GDG (NAME(MY.GDG.BASE) -
    LIMIT(7) -
    NOEMPTY -
    SCRATCH)
/*

//GDGNEW   JOB (ACCT),'NEW GDG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSIN    DD DUMMY
//SYSUT1   DD DSN=MY.INPUT.DATA,DISP=SHR
//SYSUT2   DD DSN=MY.GDG.BASE(+1),DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5)),
//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=8000)

//GDGREAD  JOB (ACCT),'READ GDG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=MYPROG
//INPUT    DD DSN=MY.GDG.BASE(0),DISP=SHR
//OUTPUT   DD SYSOUT=*

//DB2UTIL  JOB (ACCT),'DB2 UTIL',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=DSNUTILB,PARM='DB2P,RUNSTATS'
//STEPLIB  DD DSN=DB2.SDSNLOAD,DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  RUNSTATS TABLESPACE MYDB.MYTBSP
    TABLE (ALL) INDEX (ALL)
/*

//BINDJOB  JOB (ACCT),'BIND PLAN',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IKJEFT01
//STEPLIB  DD DSN=DB2.SDSNLOAD,DISP=SHR
//SYSTSPRT DD SYSOUT=*
//SYSTSIN  DD *
  DSN SYSTEM(DB2P)
  BIND PLAN(MYPLAN) -
    MEMBER(MYPROG) -
    LIBRARY('MY.DBRM.LIBRARY') -
    ACTION(REPLACE) -
    ISOLATION(CS)
  END
/*

//UNLOAD   JOB (ACCT),'UNLOAD',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=DSNUTILB,PARM='DB2P,UNLOAD'
//STEPLIB  DD DSN=DB2.SDSNLOAD,DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSREC   DD DSN=MY.UNLOAD.DATA,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(CYL,(10,5))
//SYSPUNCH DD DSN=MY.LOAD.SYSIN,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(1,1))
//SYSIN    DD *
  UNLOAD TABLESPACE MYDB.MYTBSP
/*

//SUBJOB   JOB (ACCT),'SUBMIT',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSIN    DD DUMMY
//SYSUT1   DD DSN=MY.JCL.LIBRARY(NEXTJOB),DISP=SHR
//SYSUT2   DD SYSOUT=(A,INTRDR)

//DUMMYJOB JOB (ACCT),'DUMMY DD',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=MYPROG
//SYSPRINT DD SYSOUT=*
//INPUT    DD DSN=MY.INPUT,DISP=SHR
//OUTPUT   DD DUMMY
//WORKFILE DD DUMMY

//IDCDEL   JOB (ACCT),'IDCAMS DEL',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DELETE MY.OLD.DATASET NONVSAM
  SET MAXCC = 0
/*

A JCL job has three main parts:

1. JOB Statement (required) - identifies the job:
//JOBNAME  JOB (ACCT),'DESCRIPTION',CLASS=A,MSGCLASS=X

2. EXEC Statement - executes a program or procedure:
//STEPNAME EXEC PGM=PROGNAME

3. DD Statements - define data sets:
//DDNAME   DD DSN=DATASET.NAME,DISP=SHR

Example complete job:
//MYJOB    JOB (ACCT),'MY JOB',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//DD1      DD DSN=MY.DATASET,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(5,1))
